#define PI 3.14159

#define CURVATURE             20.
#define NB_BRANCHES           6.
#define SPEED                -0.1
#define CHROMATIC_ABERRATION  1.
#define INTENSITY             1.
#define ADDED_WIDTH           0.

float distFromCenter(vec2 xy)
{
    return sqrt(xy.x*xy.x + xy.y*xy.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -0.5 to 0.5)
    vec2 uv = fragCoord/iResolution.xy - vec2(0.5, 0.5);

    vec3 col = vec3(1.0, 1.0, 1.0);

    if(CHROMATIC_ABERRATION > 0.0)
    {
        for(int i = 0; i < 3; i++)
        {
            /*
             *  The cosine of the distance from the center,
             *  the distance being offset from 0 to 1 depending
             *  on the angle formed by vec2(1, 0) and vec(uv.x, uv.y)
             *
             */ 
            col[i] =
                    cos(
                        distFromCenter(
                            uv * CURVATURE
                            +
                            CHROMATIC_ABERRATION * float(i)
                        )

                        +

                        NB_BRANCHES*2.*PI*
                        (
                            iTime * SPEED +
                                atan(uv.y, uv.x)
                                /
                                (PI * 2.)
                        )
                    ) * INTENSITY + ADDED_WIDTH;
        }
    }

    // In case of no chromatic aberration, no need to compute 3 times
    else
    {
        col = col* 
                cos(
                    distFromCenter(uv * CURVATURE) +
                    NB_BRANCHES*2.*PI*(
                        -iTime * SPEED + atan(uv.y, uv.x)
                        /(PI * 2.)
                        )
                ) * INTENSITY + ADDED_WIDTH;
    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
